const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const S = data[idx++];
const T = data[idx++];
const P = data[idx++];

const altura = new Array(S + 1);
for (let i = 1; i <= S; i++) {
  altura[i] = data[idx++];
}

const adj = Array.from({ length: S + 1 }, () => []);

for (let e = 0; e < T; e++) {
  const i = data[idx++];
  const j = data[idx++];

  if (altura[i] > altura[j]) {
    adj[i].push(j);
  } else if (altura[j] > altura[i]) {
    adj[j].push(i);
  }
}

const dp = new Array(S + 1).fill(-1);

function dfs(u) {
  if (dp[u] !== -1) return dp[u];

  let best = 1;
  for (const v of adj[u]) {
    best = Math.max(best, 1 + dfs(v));
  }

  dp[u] = best;
  return best;
}

console.log(dfs(P) - 1);
